// OpenVSwitch Daemon gRPC Service Definition
// Provides gRPC endpoints for OVSDB operations that mirror the D-Bus interface
//
// All operations flow through D-Bus as the canonical control plane per AGENTS.md

syntax = "proto3";

package ovsdaemon.v1;

// OVSDB Service - Bridge and port management
service OvsdbService {
  // Create a new OVS bridge
  rpc CreateBridge(BridgeRequest) returns (BridgeResponse);

  // Delete an OVS bridge
  rpc DeleteBridge(BridgeRequest) returns (BridgeResponse);

  // List all bridges
  rpc ListBridges(BridgesRequest) returns (BridgesResponse);

  // Add a port to a bridge
  rpc AddPort(PortRequest) returns (PortResponse);

  // List ports on a bridge
  rpc ListPorts(PortsRequest) returns (PortsResponse);

  // List OVS databases
  rpc ListDatabases(DatabaseRequest) returns (DatabaseResponse);

  // Get daemon status
  rpc GetStatus(StatusRequest) returns (StatusResponse);
}

// Bridge operations
message BridgeRequest {
  string name = 1;
}

message BridgeResponse {
  string name = 1;
  bool success = 2;
  string message = 3;
}

message BridgesRequest {
  // Empty - lists all bridges
}

message BridgesResponse {
  repeated string bridges = 1;
  int32 count = 2;
}

// Port operations
message PortRequest {
  string name = 1;
  string bridge = 2;
}

message PortResponse {
  string name = 1;
  string bridge = 2;
  bool success = 3;
  string message = 4;
}

message PortsRequest {
  string bridge = 1;
}

message PortsResponse {
  string bridge = 1;
  repeated string ports = 2;
  int32 count = 3;
}

// Database operations
message DatabaseRequest {
  // Empty - lists all databases
}

message DatabaseResponse {
  repeated string databases = 1;
  int32 count = 2;
}

// Status operations
message StatusRequest {
  // Empty
}

message StatusResponse {
  bool connected = 1;
  string version = 2;
  string message = 3;
}

//! gRPC Service for OpenVSwitch Daemon
//!
//! Provides gRPC endpoints that mirror the D-Bus interface for OVSDB operations.
//! This allows remote clients to interact with OVS over gRPC while the daemon
//! maintains D-Bus as the canonical control plane per AGENTS.md.
//!
//! The gRPC service delegates to the same `DaemonState` used by the D-Bus
//! interfaces — zero duplication, zero drift.

use anyhow::Result;
use std::net::SocketAddr;
use tonic::{Request, Response, Status};
use tracing::info;

use crate::dbus::DaemonState;

/// Generated protobuf types
pub mod proto {
    tonic::include_proto!("ovsdaemon.v1");
}

use proto::ovsdb_service_server::{OvsdbService, OvsdbServiceServer};
use proto::{
    BridgeRequest, BridgeResponse, BridgesRequest, BridgesResponse, DatabaseRequest,
    DatabaseResponse, PortRequest, PortResponse, PortsRequest, PortsResponse, StatusRequest,
    StatusResponse,
};

/// gRPC service implementation — delegates to the shared `DaemonState`.
pub struct OvsdbServiceImpl {
    state: DaemonState,
}

impl OvsdbServiceImpl {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }

    /// Helper: acquire the OVSDB client from the shared state.
    async fn ovsdb_client(
        &self,
    ) -> Result<tokio::sync::MutexGuard<'_, Option<rovs_ovsdb::Client>>, Status> {
        self.state
            .get_ovsdb()
            .await
            .map_err(|e| Status::internal(format!("OVSDB not available: {}", e)))
    }
}

#[tonic::async_trait]
impl OvsdbService for OvsdbServiceImpl {
    async fn create_bridge(
        &self,
        request: Request<BridgeRequest>,
    ) -> Result<Response<BridgeResponse>, Status> {
        let name = request.into_inner().name;
        info!("gRPC create_bridge: {}", name);

        let mut guard = self.ovsdb_client().await?;
        let client = guard
            .as_mut()
            .ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([
            {
                "op": "insert",
                "table": "Bridge",
                "row": { "name": &name, "stp_enable": false },
                "uuid-name": "new_bridge"
            },
            {
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "insert", ["named-uuid", "new_bridge"]]]
            },
        ]);

        match client.transact(ops).await {
            Ok(result) => {
                // Extract bridge UUID from result if available
                let uuid = result
                    .get("result")
                    .and_then(|r| r.as_array())
                    .and_then(|a| a.first())
                    .and_then(|o| o.get("uuid"))
                    .and_then(|u| u.as_array())
                    .and_then(|a| a.get(1))
                    .and_then(|u| u.as_str())
                    .map(|s| s.to_string())
                    .unwrap_or_default();
                Ok(Response::new(BridgeResponse {
                    name,
                    success: true,
                    message: "Bridge created".to_string(),
                    uuid,
                }))
            }
            Err(e) => Ok(Response::new(BridgeResponse {
                name,
                success: false,
                message: format!("Failed: {}", e),
                uuid: String::new(),
            })),
        }
    }

    async fn delete_bridge(
        &self,
        request: Request<BridgeRequest>,
    ) -> Result<Response<BridgeResponse>, Status> {
        let name = request.into_inner().name;
        info!("gRPC delete_bridge: {}", name);

        let mut guard = self.ovsdb_client().await?;
        let client = guard
            .as_mut()
            .ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let del_ops = serde_json::json!([
            {
                "op": "delete",
                "table": "Bridge",
                "where": [["name", "==", &name]]
            },
            {
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "delete", ["set", []]]]
            },
        ]);

        match client.transact(del_ops).await {
            Ok(_) => Ok(Response::new(BridgeResponse {
                name,
                success: true,
                message: "Bridge deleted".to_string(),
                uuid: String::new(),
            })),
            Err(e) => Ok(Response::new(BridgeResponse {
                name,
                success: false,
                message: format!("Failed: {}", e),
                uuid: String::new(),
            })),
        }
    }

    async fn list_bridges(
        &self,
        _request: Request<BridgesRequest>,
    ) -> Result<Response<BridgesResponse>, Status> {
        let mut guard = self.ovsdb_client().await?;
        let client = guard
            .as_mut()
            .ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([{
            "op": "select",
            "table": "Bridge",
            "where": [],
            "columns": ["name"]
        }]);

        match client.transact(ops).await {
            Ok(result) => {
                let bridges: Vec<String> = result
                    .get("rows")
                    .and_then(|r| r.as_array())
                    .cloned()
                    .unwrap_or_default()
                    .iter()
                    .filter_map(|r| r.get("name").and_then(|v| v.as_str()).map(String::from))
                    .collect();
                let count = bridges.len() as i32;
                Ok(Response::new(BridgesResponse { bridges, count }))
            }
            Err(e) => Err(Status::internal(format!("OVSDB query failed: {}", e))),
        }
    }

    async fn add_port(
        &self,
        request: Request<PortRequest>,
    ) -> Result<Response<PortResponse>, Status> {
        let req = request.into_inner();
        let name = req.name;
        let bridge = req.bridge;
        info!("gRPC add_port: {} to {}", name, bridge);

        let mut guard = self.ovsdb_client().await?;
        let client = guard
            .as_mut()
            .ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([
            {
                "op": "insert",
                "table": "Interface",
                "row": { "name": &name, "type": "system" },
                "uuid-name": "new_iface"
            },
            {
                "op": "insert",
                "table": "Port",
                "row": {
                    "name": &name,
                    "interfaces": ["set", [["named-uuid", "new_iface"]]]
                },
                "uuid-name": "new_port"
            },
            {
                "op": "mutate",
                "table": "Bridge",
                "where": [["name", "==", &bridge]],
                "mutations": [["ports", "insert", ["named-uuid", "new_port"]]]
            },
        ]);

        match client.transact(ops).await {
            Ok(_) => Ok(Response::new(PortResponse {
                name,
                bridge,
                success: true,
                message: "Port added".to_string(),
                uuid: String::new(),
            })),
            Err(e) => Ok(Response::new(PortResponse {
                name,
                bridge,
                success: false,
                message: format!("Failed: {}", e),
                uuid: String::new(),
            })),
        }
    }

    async fn list_ports(
        &self,
        request: Request<PortsRequest>,
    ) -> Result<Response<PortsResponse>, Status> {
        let bridge = request.into_inner().bridge;
        let mut guard = self.ovsdb_client().await?;
        let client = guard
            .as_mut()
            .ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([{
            "op": "select",
            "table": "Bridge",
            "where": [["name", "==", &bridge]],
            "columns": ["ports"]
        }]);

        match client.transact(ops).await {
            Ok(result) => {
                let mut ports = Vec::new();
                if let Some(rows) = result.get("rows").and_then(|r| r.as_array()) {
                    if let Some(first) = rows.first() {
                        if let Some(port_set) = first.get("ports").and_then(|p| p.as_array()) {
                            for item in port_set.iter().skip(1) {
                                if let Some(uuid_arr) = item.as_array() {
                                    if uuid_arr.len() == 2 && uuid_arr[0] == "uuid" {
                                        if let Some(uuid) = uuid_arr[1].as_str() {
                                            let name_ops = serde_json::json!([{
                                                "op": "select",
                                                "table": "Port",
                                                "where": [["_uuid", "==", ["uuid", uuid]]],
                                                "columns": ["name"]
                                            }]);
                                            if let Ok(name_result) = client.transact(name_ops).await
                                            {
                                                if let Some(name_rows) = name_result
                                                    .get("rows")
                                                    .and_then(|r| r.as_array())
                                                {
                                                    if let Some(name_row) = name_rows.first() {
                                                        if let Some(port_name) = name_row
                                                            .get("name")
                                                            .and_then(|n| n.as_str())
                                                        {
                                                            ports.push(port_name.to_string());
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                let count = ports.len() as i32;
                Ok(Response::new(PortsResponse {
                    bridge,
                    ports,
                    count,
                }))
            }
            Err(e) => Err(Status::internal(format!("OVSDB query failed: {}", e))),
        }
    }

    async fn remove_port(
        &self,
        request: Request<PortRequest>,
    ) -> Result<Response<PortResponse>, Status> {
        let req = request.into_inner();
        let name = req.name;
        let bridge = req.bridge;
        info!("gRPC remove_port: {} from {}", name, bridge);

        let mut guard = self.ovsdb_client().await?;
        let client = guard
            .as_mut()
            .ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([
            {
                "op": "mutate",
                "table": "Bridge",
                "where": [["name", "==", &bridge]],
                "mutations": [["ports", "delete", ["name", &name]]]
            },
            {
                "op": "delete",
                "table": "Port",
                "where": [["name", "==", &name]]
            },
            {
                "op": "delete",
                "table": "Interface",
                "where": [["name", "==", &name]]
            },
        ]);

        match client.transact(ops).await {
            Ok(_) => Ok(Response::new(PortResponse {
                name,
                bridge,
                success: true,
                message: "Port removed".to_string(),
                uuid: String::new(),
            })),
            Err(e) => Ok(Response::new(PortResponse {
                name,
                bridge,
                success: false,
                message: format!("Failed: {}", e),
                uuid: String::new(),
            })),
        }
    }

    async fn list_databases(
        &self,
        _request: Request<DatabaseRequest>,
    ) -> Result<Response<DatabaseResponse>, Status> {
        let mut guard = self.ovsdb_client().await?;
        let client = guard
            .as_mut()
            .ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        match client.list_dbs().await {
            Ok(dbs) => {
                let count = dbs.len() as i32;
                Ok(Response::new(DatabaseResponse {
                    databases: dbs,
                    count,
                }))
            }
            Err(e) => Err(Status::internal(format!("OVSDB query failed: {}", e))),
        }
    }

    async fn get_status(
        &self,
        _request: Request<StatusRequest>,
    ) -> Result<Response<StatusResponse>, Status> {
        let connected = self.state.get_ovsdb().await.is_ok();
        Ok(Response::new(StatusResponse {
            connected,
            version: env!("CARGO_PKG_VERSION").to_string(),
            message: if connected {
                "Daemon connected to OVSDB".to_string()
            } else {
                "Daemon not connected to OVSDB".to_string()
            },
        }))
    }
}

/// Run the gRPC server
pub async fn run_grpc_server(addr: SocketAddr, state: DaemonState) -> Result<()> {
    info!("gRPC server starting on {}", addr);

    let service = OvsdbServiceImpl::new(state);

    tonic::transport::Server::builder()
        .add_service(OvsdbServiceServer::new(service))
        .serve(addr)
        .await
        .map_err(|e| anyhow::anyhow!("gRPC server error: {}", e))?;

    Ok(())
}

/// Run the gRPC server with streaming support (M2: gRPC transport + projection wiring)
pub async fn run_grpc_server_with_streaming(
    addr: SocketAddr,
    state: DaemonState,
    streaming_service: crate::grpc_streaming::StreamingService,
) -> Result<()> {
    info!("gRPC server with streaming starting on {}", addr);

    let base_service = OvsdbServiceImpl::new(state);
    let stream_server = streaming_service.into_server();

    tonic::transport::Server::builder()
        .add_service(OvsdbServiceServer::new(base_service))
        .add_service(stream_server)
        .serve(addr)
        .await
        .map_err(|e| anyhow::anyhow!("gRPC server error: {}", e))?;

    Ok(())
}

syntax = "proto3";

package ovsdaemon.v1;

// Base OVSDB service for bridge/port management
// Provides typed gRPC interface over OVSDB operations
service OvsdbService {
    // Bridge operations
    rpc CreateBridge(BridgeRequest) returns (BridgeResponse);
    rpc DeleteBridge(BridgeRequest) returns (BridgeResponse);
    rpc ListBridges(BridgesRequest) returns (BridgesResponse);

    // Port operations
    rpc AddPort(PortRequest) returns (PortResponse);
    rpc RemovePort(PortRequest) returns (PortResponse);
    rpc ListPorts(PortsRequest) returns (PortsResponse);

    // Database operations
    rpc ListDatabases(DatabaseRequest) returns (DatabaseResponse);

    // Status
    rpc GetStatus(StatusRequest) returns (StatusResponse);
}

// Bridge request/response
message BridgeRequest {
    string name = 1;
    string datapath_id = 2;
    map<string, string> options = 3;
}

message BridgeResponse {
    string name = 1;
    bool success = 2;
    string message = 3;
    string uuid = 4;
}

message BridgesRequest {
    // Optional filter
    string filter = 1;
}

message BridgesResponse {
    repeated string bridges = 1;
    int32 count = 2;
}

// Port request/response
message PortRequest {
    string name = 1;
    string bridge = 2;
    string interface_type = 3;  // system, internal, vxlan, etc.
    map<string, string> options = 4;
}

message PortResponse {
    string name = 1;
    string bridge = 2;
    bool success = 3;
    string message = 4;
    string uuid = 5;
}

message PortsRequest {
    string bridge = 1;
}

message PortsResponse {
    string bridge = 1;
    repeated string ports = 2;
    int32 count = 3;
}

// Database operations
message DatabaseRequest {
    // Empty or specific database name
    string database = 1;
}

message DatabaseResponse {
    repeated string databases = 1;
    int32 count = 2;
}

// Status
message StatusRequest {}

message StatusResponse {
    bool connected = 1;
    string version = 2;
    string message = 3;
}

//! Pure passthrough D-Bus interfaces for the op-openvswitch-daemon.
//!
//! TWO separate object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → interface `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → interface `org.opdbus.rovs.openflow`
//!
//! The daemon knows NOTHING about bridges, ports, or containers.  It only
//! proxies raw `rovs-jsonrpc` / `rovs-openflow` primitives over D-Bus.
//! Business logic lives in the consuming plugins.

use anyhow::{Context, Result};
use rovs_ovsdb::Client;
use rovs_transport::Address;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{debug, info};
use zbus::interface;

// ── Shared daemon state ───────────────────────────────────────────────────────

/// Global state shared by both D-Bus objects.
#[derive(Clone)]
pub struct DaemonState {
    /// OVSDB JSON-RPC client (rovs_ovsdb).  Lazily initialised on first call.
    pub ovsdb: Arc<Mutex<Option<Client>>>,
    /// OVS Unix-domain socket path.
    pub socket_path: String,
    /// OpenFlow connections: conn_id → VConn.
    pub of_conns: Arc<Mutex<HashMap<u64, rovs_openflow::VConn>>>,
    /// Monotonic connection handle allocator.
    pub next_of_id: Arc<Mutex<u64>>,
}

impl DaemonState {
    pub fn new(socket_path: String) -> Self {
        Self {
            ovsdb: Arc::new(Mutex::new(None)),
            socket_path,
            of_conns: Arc::new(Mutex::new(HashMap::new())),
            next_of_id: Arc::new(Mutex::new(1)),
        }
    }

    /// Get or create the persistent OVSDB client.
    pub async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<'_, Option<Client>>> {
        let mut guard = self.ovsdb.lock().await;
        if guard.is_none() {
            let client = Client::connect(&format!("unix:{}", self.socket_path))
                .await
                .with_context(|| format!("connect to OVSDB at {}", self.socket_path))?;
            info!("OVSDB client connected to {}", self.socket_path);
            *guard = Some(client);
        }
        Ok(guard)
    }

    /// Allocate a new OpenFlow connection handle id.
    pub async fn alloc_of_id(&self) -> u64 {
        let mut n = self.next_of_id.lock().await;
        let id = *n;
        *n += 1;
        id
    }
}

// ── JSON-RPC object (/org/opdbus/rovs/jsonrpc) ──────────────────────────────

/// D-Bus service proxying raw `rovs-jsonrpc` + `rovs-ovsdb` primitives.
pub struct JsonRpcService {
    state: DaemonState,
}

impl JsonRpcService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.rovs.jsonrpc")]
impl JsonRpcService {
    /// Execute a raw OVSDB JSON-RPC `transact`.
    ///
    /// `method` — JSON-RPC method name (always `"transact"` for OVSDB).
    /// `params_json` — JSON-encoded params array (e.g. `["Open_vSwitch", {op:...}]`).
    /// Returns JSON-encoded result.
    async fn transact(&self, method: &str, params_json: &str) -> String {
        debug!(
            "jsonrpc.transact method={} params_len={}",
            method,
            params_json.len()
        );

        let mut guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
        };
        let client = match guard.as_mut() {
            Some(c) => c,
            None => return json_error("OVSDB client unavailable"),
        };

        // Parse params as serde_json::Value array.
        let params: serde_json::Value = match serde_json::from_str(params_json) {
            Ok(v) => v,
            Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
        };

        // We use the rovs_ovsdb::Client::transact_raw or similar.
        // Since rovs_ovsdb::Client exposes `transact(Value) -> Result<Value>`,
        // we forward directly.
        match client.transact(params).await {
            Ok(result) => match serde_json::to_string(&result) {
                Ok(s) => s,
                Err(e) => json_error(&format!("serialize result failed: {}", e)),
            },
            Err(e) => json_error(&format!("transact failed: {}", e)),
        }
    }

    /// One-way notify (fire-and-forget).
    async fn notify(&self, _method: &str, _params_json: &str) {
        // rovs-jsonrpc notify support — placeholder; most callers use transact.
        debug!("jsonrpc.notify (passthrough stub)");
    }

    /// Return next JSON-RPC request id (monotonic counter).
    async fn next_id(&self) -> u64 {
        // Simplistic id counter.  In full rovs-jsonrpc this is per-connection.
        1
    }

    /// Send raw JSON-RPC message string, return response string.
    async fn send_message(&self, msg: &str) -> String {
        debug!("jsonrpc.send_message len={}", msg.len());
        match serde_json::from_str::<serde_json::Value>(msg) {
            Ok(req) => {
                let mut guard = match self.state.get_ovsdb().await {
                    Ok(g) => g,
                    Err(e) => return json_error(&format!("connect failed: {}", e)),
                };
                let client = match guard.as_mut() {
                    Some(c) => c,
                    None => return json_error("client unavailable"),
                };
                match client.transact(req).await {
                    Ok(r) => {
                        serde_json::to_string(&r).unwrap_or_else(|e| json_error(&e.to_string()))
                    }
                    Err(e) => json_error(&e.to_string()),
                }
            }
            Err(e) => json_error(&format!("invalid JSON: {}", e)),
        }
    }

    /// Receive raw JSON-RPC message string.
    async fn recv_message(&self) -> String {
