// ── Internal rtnetlink helpers ──────────────────────────────────────────────────

fn rename_link_rtnetlink(old_name: &str, new_name: &str) -> Result<()> {
    let rt = tokio::runtime::Handle::current();
    rt.block_on(async {
        let (connection, handle, _) = rtnetlink::new_connection()
            .context("connect to rtnetlink")?;
        tokio::spawn(connection);

        let mut links = handle.link().get().name_match(old_name.to_string()).execute();
        let link = links.next().await
            .ok_or_else(|| anyhow::anyhow!("interface {} not found in netns", old_name))?;

        handle.link().set(link.header.index)
            .name(new_name.to_string())
            .execute()
            .await
            .with_context(|| format!("rename {} to {}", old_name, new_name))?;

        Result::<()>::Ok(())
    })
}

fn set_link_up_rtnetlink(ifname: &str) -> Result<()> {
    let rt = tokio::runtime::Handle::current();
    rt.block_on(async {
        let (connection, handle, _) = rtnetlink::new_connection()
            .context("connect to rtnetlink")?;
        tokio::spawn(connection);

        let mut links = handle.link().get().name_match(ifname.to_string()).execute();
        let link = links.next().await
            .ok_or_else(|| anyhow::anyhow!("interface {} not found", ifname))?;

        handle.link().set(link.header.index)
            .up()
            .execute()
            .await
            .with_context(|| format!("set {} up", ifname))?;

        Result::<()>::Ok(())
    })
}

fn add_addr_rtnetlink(ifname: &str, addr: &str) -> Result<()> {
    let rt = tokio::runtime::Handle::current();
    rt.block_on(async {
        let (connection, handle, _) = rtnetlink::new_connection()
            .context("connect to rtnetlink")?;
        tokio::spawn(connection);

        let mut links = handle.link().get().name_match(ifname.to_string()).execute();
        let link = links.next().await
            .ok_or_else(|| anyhow::anyhow!("interface {} not found", ifname))?;

        let addr_val: std::net::IpAddr = addr.parse()
            .with_context(|| format!("parse IP address {}", addr))?;

        handle.address().add(link.header.index, addr_val, 0).execute()
            .await
            .with_context(|| format!("add addr {} to {}", addr, ifname))?;

        Result::<()>::Ok(())
    })
}

/// Create an OVS internal port via OVSDB transact, then move it into a container's netns,
/// rename it, bring it up, and optionally add an IP address.
///
/// This is the full "attach" operation for the openvswitch proxy.
pub fn attach_port_to_container(
    port_name: &str,
    bridge: &str,
    target_pid: u32,
    iface_name: &str,
    ip_addrs: &[&str],
) -> Result<()> {
    info!(
        "attach: creating OVS internal port {} on {} for PID {}",
        port_name, bridge, target_pid
    );

    // Step 1: Move the OVS internal port into the container's netns
    move_interface_to_netns(port_name, target_pid)?;

    // Step 2: Rename inside the container's netns
    if port_name != iface_name {
        rename_in_netns(port_name, iface_name, target_pid)?;
    }

    // Step 3: Bring the interface UP inside the container
    set_link_up_in_netns(iface_name, target_pid)?;

    // Step 4: Add IP addresses
    for addr in ip_addrs {
        match add_addr_in_netns(iface_name, addr, target_pid) {
            Ok(_) => info!("attach: added addr {} to {}", addr, iface_name),
            Err(e) => warn!("attach: failed to add addr {} to {}: {}", addr, iface_name, e),
        }
    }

    info!(
        "attach: {} -> {} in PID {} complete",
        port_name, iface_name, target_pid
    );
    Ok(())
}

/// Detach: remove an OVS port from the bridge (works regardless of which netns it's in,
/// since OVSDB operations are namespace-agnostic — OVS owns the port in the bridge table).
pub fn detach_port_from_bridge(port_name: &str, bridge: &str) -> Result<()> {
    info!("detach: removing {} from {}", port_name, bridge);
    // The actual OVSDB transact is done by the caller (gRPC/D-Bus handler)
    // This function is a placeholder for any host-side cleanup needed
    // after the port is removed from OVS (e.g. if the port was left in
    // a container's netns, it would return to the host automatically on
    // container stop).
    Ok(())
}


