                return serde_json::json!({
                    "success": false,
                    "message": format!("rename in netns failed: {}", e),
                    "iface_name": iface_name
                })
                .to_string();
            }
        }

        let _ = crate::netns::set_link_up_in_netns(&iface_name, target_pid);

