    ///
    /// To Remove a link from a bridge, set its master to zero.
    /// This is equvalent to `ip link set LINK nomaster`
    pub fn controller(mut self, ctrl_index: u32) -> Self {
        self.message
            .attributes
            .push(LinkAttribute::Controller(ctrl_index));
        self
    }


