//! ovs-attach — D-Bus client that calls AttachPort for container bootstrap.
//!
//! Runs inside the container at boot. Connects to the op-dbus session bus,
//! calls the host's op-openvswitch-daemon to create an OVS internal port,
//! move it into this container's netns, and configure IPs/routes.

use anyhow::{Context, Result};
use serde_json::json;
use std::env;
use std::fs;
use std::path::Path;
use std::process::Command;
use std::thread;
use std::time::Duration;
use zbus::zvariant::Value;

const DBUS_SOCKET: &str = "/run/op-dbus.sock";
const BUS_NAME: &str = "org.opdbus.v1.plugins.ovsdb";
const OBJECT_PATH: &str = "/org/opdbus/rovs/proxy";
const INTERFACE: &str = "org.opdbus.rovs.proxy";

fn main() -> Result<()> {
    let port_name = env::args()
        .nth(1)
        .unwrap_or_else(|| "wg-xray-net0".into());
    let bridge = env::args().nth(2).unwrap_or_else(|| "ovsbr0".into());
    let iface = env::args().nth(3).unwrap_or_else(|| "eth0".into());

    // Wait for D-Bus socket
    eprintln!("waiting for D-Bus socket at {DBUS_SOCKET}...");
    for i in 0..60 {
        if Path::new(DBUS_SOCKET).exists() {
            break;
        }
        if i == 59 {
            anyhow::bail!("D-Bus socket not found after 60s");
        }
        thread::sleep(Duration::from_secs(1));
    }

    // Check if interface already exists
    if Command::new("ip")
        .args(["link", "show", &iface])
        .output()
        .is_ok_and(|o| o.status.success())
    {
        eprintln!("interface {iface} already exists, skipping");
        return Ok(());
    }

    // Build AttachPort params
    let params = json!({
        "port_name": port_name,
        "bridge": bridge,
        "target_pid": 1,
        "iface_name": iface,
        "ip_addrs": ["10.200.0.1/30", "10.0.0.2/24"],
        "gateway": "10.200.0.2",
        "routes": ["10.0.0.1 via 10.200.0.2"]
    });

    // Connect to D-Bus via zbus
    let address = format!("unix:path={DBUS_SOCKET}");
    eprintln!("connecting to D-Bus at {address}...");

    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()?;
    rt.block_on(async {
        let conn = zbus::ConnectionBuilder::address(&*address)?
            .build()
            .await
            .context("connect to D-Bus")?;

        eprintln!("calling AttachPort...");
        let result: String = conn
            .call_method(
                Some(BUS_NAME),
                OBJECT_PATH,
                Some(INTERFACE),
                "AttachPort",
                &(params.to_string()),
            )
            .await?
            .body()
            .deserialize()?;

        eprintln!("AttachPort result: {result}");

        // Parse result
        let parsed: serde_json::Value = serde_json::from_str(&result)?;
        if parsed["success"].as_bool() != Some(true) {
            anyhow::bail!("AttachPort failed: {}", parsed["message"]);
        }

        Ok(())
    })?;

    // Wait for interface to appear
    eprintln!("waiting for interface {iface}...");
    for i in 0..30 {
        if Command::new("ip")
            .args(["link", "show", &iface])
            .output()
            .is_ok_and(|o| o.status.success())
        {
            eprintln!("interface {iface} is up");
            return Ok(());
        }
        thread::sleep(Duration::from_secs(1));
    }

    anyhow::bail!("interface {iface} not found after 30s")
}

