//! Container ID to host PID resolution via incus.

use anyhow::{Context, Result};

/// Resolve an incus container ID to its host-side PID.
///
/// Uses `incus list --format json` to find the container matching the
/// numeric instance ID, then returns its init PID on the host.
pub fn pid_from_container_id(container_id: u64) -> Result<u32> {
    let output = std::process::Command::new("incus")
        .args(["list", "--format", "json"])
        .output()
        .context("spawn incus list")?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        anyhow::bail!("incus list failed: {}", stderr.trim());
    }

    let instances: serde_json::Value =
        serde_json::from_slice(&output.stdout).context("parse incus list JSON")?;

    let instances_arr = instances
        .as_array()
        .ok_or_else(|| anyhow::anyhow!("incus list returned non-array"))?;

    for inst in instances_arr {
        // Check if this instance matches the container_id
        // incus uses "name" as the primary key, but container_id in our schema
        // maps to incus instance names like "101" or the actual instance name
        let name = inst["name"].as_str().unwrap_or("");
        let state = &inst["state"];

        // Try matching by name (container_id as string) or by instance id
        let matches = name == container_id.to_string()
            || inst["id"].as_u64() == Some(container_id);

        if matches {
            let pid = state["pid"]
                .as_u64()
                .or_else(|| state["processes"]["init"]["pid"].as_u64())
                .or_else(|| {
                    // Try nested state structure
                    inst["state"]["pid"].as_u64()
                });

            if let Some(pid) = pid {
                if pid > 0 {
                    return Ok(pid as u32);
                }
            }

            // If no PID in JSON, try incus info
            return pid_from_incus_info(name);
        }
    }

    anyhow::bail!("container_id {} not found in incus list", container_id)
}

/// Fallback: get PID from `incus info <name>`.
fn pid_from_incus_info(name: &str) -> Result<u32> {
    let output = std::process::Command::new("incus")
        .args(["info", name])
        .output()
        .context("spawn incus info")?;

    if !output.status.success() {
        anyhow::bail!("incus info {} failed", name);
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    for line in stdout.lines() {
        if line.contains("PID:") {
            let pid_str = line.split(':').nth(1).unwrap_or("").trim();
            let pid: u32 = pid_str
                .parse()
                .context(format!("parse PID from '{}'", line))?;
            if pid > 0 {
                return Ok(pid);
            }
        }
    }

    anyhow::bail!("no PID found in incus info for {}", name)
}

