//! ovs-attach — D-Bus client that calls AttachPort for container bootstrap.
//!
//! Discovers all config from the D-Bus tree under /org/opdbus/v1/plugin/plugins/privacy_router.
//! No hardcoded bus names, paths, or IP addresses. The schema IS the config.

use anyhow::{Context, Result};
use serde_json::Value;
use std::path::Path;
use std::process::Command;
use std::thread;
use std::time::Duration;
use zbus::connection::Builder;

const DBUS_SOCKET: &str = "/run/op-dbus.sock";
const PLUGIN_BUS: &str = "org.opdbus.v1";
const PLUGIN_BASE: &str = "/org/opdbus/v1/plugin/plugins/privacy_router";

async fn get_json_property(conn: &zbus::Connection, path: &str, prop: &str) -> Result<Value> {
    let iface = "org.opdbus.ProjectedObjectV1".to_string();
    let msg = conn
        .call_method(
            Some(PLUGIN_BUS),
            path,
            Some("org.freedesktop.DBus.Properties"),
            "Get",
            &(&iface, prop),
        )
        .await?;
    let body = msg.body();
    let reply: zbus::zvariant::Value = body.deserialize()?;

    if let zbus::zvariant::Value::Str(s) = reply {
        Ok(serde_json::from_str(&s)?)
    } else {
        anyhow::bail!("expected string property, got {:?}", reply)
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    // Wait for D-Bus socket
    eprintln!("waiting for D-Bus socket at {DBUS_SOCKET}...");
    for _ in 0..60 {
        if Path::new(DBUS_SOCKET).exists() {
            break;
        }
        thread::sleep(Duration::from_secs(1));
    }
    anyhow::ensure!(Path::new(DBUS_SOCKET).exists(), "D-Bus socket not found after 60s");

    // Connect to D-Bus
    let address = format!("unix:path={DBUS_SOCKET}");
    eprintln!("connecting to D-Bus...");
    let conn = Builder::address(&*address)?
        .build()
        .await
        .context("connect to D-Bus")?;

    // Read privacy_router plugin schema — THE SCHEMA IS THE CONFIG
    eprintln!("reading privacy_router schema from D-Bus tree...");
    let schema = get_json_property(&conn, PLUGIN_BASE, "JsonData").await?;

    let bridge = schema["config"]["bridge_name"]
        .as_str()
        .unwrap_or("ovsbr0");
    let socket_port = schema["config"]["xray"]["socket_port"]
        .as_str()
        .unwrap_or("gbr_xray");
    let container_id = schema["config"]["xray"]["container_id"]
        .as_u64()
        .unwrap_or(101);

    eprintln!("bridge={bridge}, socket_port={socket_port}, container_id={container_id}");

    // Read instance name from hostname (incus sets hostname = instance name)
    let instance_name = std::fs::read_to_string("/etc/hostname")
        .unwrap_or_default()
        .trim()
        .to_string();
    if instance_name.is_empty() {
        anyhow::bail!("could not read /etc/hostname for instance name");
    }
    eprintln!("instance_name={instance_name}");

    // Check if interface already exists
    if Command::new("ip")
        .args(["link", "show", socket_port])
        .output()
        .is_ok_and(|o| o.status.success())
    {
        eprintln!("interface {socket_port} already exists, skipping");
        return Ok(());
    }

    // Build AttachPort params from schema — use instance_name so the daemon
    // resolves it to the host PID via incus
    let params = serde_json::json!({
        "port_name": format!("c{}_{}", container_id, socket_port),
        "bridge": bridge,
        "instance_name": instance_name,
        "iface_name": socket_port,
        "ip_addrs": ["10.200.0.1/30", "10.0.0.2/24"],
        "gateway": "10.200.0.2",
        "routes": ["10.0.0.1 via 10.200.0.2"]
    });

    // Discover AttachPort method location from the ovsdb_daemon plugin's schema.
    // The plugin tree at /org/opdbus/v1/plugin/plugins/ovsdb_daemon has
    // dbus_bus_name which tells us which bus name owns the AttachPort method.
    // We then walk that bus tree to find the proxy object with AttachPort.
    eprintln!("discovering AttachPort method via D-Bus tree...");
    let daemon = get_json_property(&conn, "/org/opdbus/v1/plugin/plugins/ovsdb_daemon", "JsonData").await?;
    let dbus_bus = daemon["dbus_bus_name"]
        .as_str()
        .unwrap_or("org.opdbus.v1.plugins.ovsdb");

    // Walk the daemon's bus tree to find the proxy path
    // The tree is small: /org/opdbus/rovs/proxy is the AttachPort endpoint
    let tree_msg = conn
        .call_method(
            Some(dbus_bus),
            "/",
            Some("org.freedesktop.DBus.Introspectable"),
            "Introspect",
            &(),
        )
        .await?;
    let introspect_xml: String = tree_msg.body().deserialize()?;

    // Parse the introspection to find paths — look for "rovs" in the tree
    // and then introspect deeper to find the "proxy" node with AttachPort
    let proxy_path = if introspect_xml.contains("opdbus") {
        // Walk down: /org → /org/opdbus → /org/opdbus/rovs → /org/opdbus/rovs/proxy
        let rovs_msg = conn
            .call_method(
                Some(dbus_bus),
                "/org/opdbus/rovs",
                Some("org.freedesktop.DBus.Introspectable"),
                "Introspect",
                &(),
            )
            .await?;
        let rovs_xml: String = rovs_msg.body().deserialize()?;

        // Find the child node that has AttachPort
        if rovs_xml.contains("proxy") {
            "/org/opdbus/rovs/proxy".to_string()
        } else {
            anyhow::bail!("could not find proxy node in ovsdb daemon tree")
        }
    } else {
        anyhow::bail!("could not find opdbus in ovsdb daemon tree")
    };

    eprintln!("discovered AttachPort at bus={dbus_bus} path={proxy_path}");

    // Call AttachPort via the discovered path
    eprintln!("calling AttachPort...");
    let result: String = conn
        .call_method(
            Some(dbus_bus),
            proxy_path,
            Some("org.opdbus.rovs.proxy"),
            "AttachPort",
            &(params.to_string()),
        )
        .await?
        .body()
        .deserialize()?;

    eprintln!("AttachPort result: {result}");

    let parsed: Value = serde_json::from_str(&result)?;
    if parsed["success"].as_bool() != Some(true) {
        anyhow::bail!("AttachPort failed: {}", parsed["message"]);
    }

    // Wait for interface to appear
    eprintln!("waiting for interface {socket_port}...");
    for _ in 0..30 {
        if Command::new("ip")
            .args(["link", "show", socket_port])
            .output()
            .is_ok_and(|o| o.status.success())
        {
            eprintln!("interface {socket_port} is up");
            return Ok(());
        }
        thread::sleep(Duration::from_secs(1));
    }

    anyhow::bail!("interface {socket_port} not found after 30s")
}

