//! OCI container plugin — schema-driven lifecycle for Docker/OCI containers
//! managed by incus that need host-side bootstrap (loopback, netns init).
//!
//! OCI containers in incus with no NIC device boot with lo DOWN, preventing
//! services from binding to 127.0.0.1. This plugin declares which containers
//! need loopback bring-up, and the op-openvswitch-daemon's BringUpLoopback
//! D-Bus method executes it.
//!
//! THE PLUGIN IS THE SCHEMA — if a container is declared here with
//! loopback_required=true, the daemon will bring up lo inside its netns.

use anyhow::Result;
use chrono::Utc;
use op_state_store::{StateDiff, DiffMetadata, ApplyResult, PluginSchema};
use serde_json::{Value, json};
use super::plugin_schema_defs;

pub struct OciPlugin;

impl OciPlugin {
    pub fn new() -> Self {
        Self
    }
}

impl op_state_store::StatePlugin for OciPlugin {
    fn name(&self) -> &str {
        "oci"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn category(&self) -> &str {
        "container"
    }

    fn is_external(&self) -> bool {
        true
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(plugin_schema_defs::oci_plugin_schema())
    }

    async fn query_current_state(&self) -> Result<Value> {
        Ok(json!({
            "containers": [],
            "daemon_status": "unknown"
        }))
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            message: "oci plugin: state is managed via D-Bus BringUpLoopback/ContainerInit".to_string(),
            changed: false,
        })
    }
}

