/// Check if the current container instance has loopback_required in the incus schema.
async fn check_loopback_required(conn: &zbus::Connection, instance_name: &str) -> Result<bool> {
    let incus_schema = get_json_property(conn, INCUS_BASE, "JsonData").await?;

    if let Some(instances) = incus_schema["config"]["instances"].as_array() {
        for inst in instances {
            if inst["name"].as_str() == Some(instance_name) {
                return Ok(inst["loopback_required"].as_bool().unwrap_or(false));
            }
        }
    }
    Ok(false)
}

