pub(crate) use super::fail2ban::fail2ban_plugin_schema;
pub(crate) use super::gcloud_adc::gcloud_adc_plugin_schema;
pub(crate) use super::hardware::hardware_plugin_schema;
pub(crate) use super::incus::incus_plugin_schema;
pub(crate) use super::keypair::keypair_plugin_schema;
pub(crate) use super::knowledge_plugin::knowledge_plugin_schema;
