// ── Shared utility functions (not schemas) ─────────────────────────────────────

use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema};
use simd_json::{json, OwnedValue as Value};

/// Format a plugin's live state into a `PluginSchema`.
///
/// This is a *formatter*, not a schema authority — nothing here is indexed.
/// The plugin's `query_current_state()` is the single source of truth; field
/// types are inferred from that state, so the schema can never drift from what
/// the plugin actually reports. To add a field, add it to the plugin state —
/// never hand-write a field definition.
pub(crate) fn schema_from_state(
    name: &str,
    category: &str,
    version: &str,
    description: &str,
    state: &Value,
) -> PluginSchema {
    use simd_json::prelude::*;

    let mut builder = PluginSchema::builder(name)
        .version(version)
        .category(category)
        .description(description);

    if let Some(obj) = state.as_object() {
        for (key, value) in obj.iter() {
            builder = builder.field(&key.to_string(), field_from_value(value));
        }
    }

    builder.example(state.clone()).build()
}

/// Infer a `FieldSchema` (type + example) from a live state value.
pub(crate) fn field_from_value(value: &Value) -> FieldSchema {
