/// Check if the Secret Service is available on the session bus
fn check_service_available(&self) -> bool {
    // Use dbus-send to synchronously check if org.freedesktop.secrets
    // is registered on the session bus. This avoids the async constraint
    // of is_available() while giving an accurate answer.
    std::process::Command::new("dbus-send")
        .args([
            "--session",
            "--dest=org.freedesktop.DBus",
            "--type=method_call",
            "--print-reply",
            "/org/freedesktop/DBus",
            "org.freedesktop.DBus.NameHasOwner",
            "string:org.freedesktop.secrets",
        ])
        .output()
        .map(|o| {
            String::from_utf8_lossy(&o.stdout).contains("boolean true")
        })
        .unwrap_or(false)
}

