    let locked: bool = proxy.call("Locked", &()).await?;
    let created: u64 = proxy.call("Created", &()).await?;
    let modified: u64 = proxy.call("Modified", &()).await?;

    Ok(CollectionInfo {
        path: path.to_string(),
        label,
        locked,
        created,
        modified,
    })
}

